WITH metrics AS (SELECT *, FIRST_VALUE(discount) IGNORE NULLS OVER (ORDER BY discount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_discount, SUM(amount) OVER (PARTITION BY status ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_amount, NTILE(10) OVER (PARTITION BY channel ORDER BY amount, id) amount_bucket FROM orders) SELECT CASE WHEN shipping_fee >= 41 THEN 'HIGH' ELSE 'LOW' END AS shipping_fee_tier, channel, SIZE(COLLECT_SET(channel)) AS num_channels, SORT_ARRAY(COLLECT_SET(channel)) AS channel_list, COUNT(*) AS event_count, MAX(amount_bucket) FILTER (WHERE status = 'COMPLETED') AS completed_max_amount_bucket, ROUND(AVG(amount), 2) AS avg_amount FROM metrics GROUP BY CASE WHEN shipping_fee >= 41 THEN 'HIGH' ELSE 'LOW' END, channel ORDER BY channel DESC
